L["Nudge X"] = "Feinjustierung X"
L["A small shift left or right from the anchor, wherever the anchor is."] = "Eine kleine Verschiebung nach links oder rechts vom Anker, wo auch immer er ist."
L["Nudge Y"] = "Feinjustierung Y"
L["A small shift up or down from the anchor."] = "Eine kleine Verschiebung nach oben oder unten vom Anker."
L["Layout"] = "Anordnung"
L["Stacked puts the rows one under another. Radial spreads them along an arc around the anchor."] = "„Gestapelt“ setzt die Zeilen untereinander. „Kreisbogen“ verteilt sie auf einem Bogen um den Anker."
L["Direction"] = "Richtung"
L["Vertical puts the rows one under another; Horizontal puts them side by side in a line."] = "„Senkrecht“ setzt die Zeilen untereinander, „Waagerecht“ nebeneinander in eine Reihe."
L["Grow"] = "Wachstum"
L["Which way new rows are added."] = "In welche Richtung neue Zeilen hinzukommen."
L["Which way the line runs from the anchor: left, right, or out both ways with the line centred on it."] = "In welche Richtung die Reihe vom Anker aus läuft: nach links, nach rechts oder in beide Richtungen, mittig um den Anker."
